// Pack independence (extending.md; the canon-side `pack-independence` barrier):
// packs no longer import each other's code — a fixed folder-barrier is now
// CONTRIBUTED as manifest data (`requires` the mechanism pack +
// `contributes` on pack.mjs; the engine builds the rule) and the shared
// path/migration helpers moved into the vendored engine lib (engine/checks/helpers/).
// The old code-composition export (`defineBarrier`) is gone.
//
// Canon-side the conversion is complete (rule first, then the fixes — one
// commit each). Member-side there are no mechanical ops: nothing in a
// consumer's tree is renamed or rewritten. The AGENTIC note for the nightly
// worker: if a member's own local packs (.claudinite/local_packs/) composed a
// barrier by importing the shared engine, convert each to the contribution
// shape — move the barrier object (id, edges, description, why, doc,
// crossingExcuse, gateDir) onto the local pack's manifest under
// `contributes` and add the mechanism pack to its `requires`. A local pack
// still importing the removed export fails loudly at pack discovery (the
// runner's fail-soft config finding names the broken manifest) — that
// diagnostic is the member-side signal. Consumers with no such local packs
// need nothing.
//
// retire: 'auto' — the durable enforcement is the check, which every member
// runs from its own snapshot; this record only carries the one-time
// conversion guidance through the fleet's next cycles.
export default {
  id: 'pack-independence',
  landed: '2026-07-19',
  summary: 'packs compose by declaration + contributed config, never code imports; local packs that imported the shared barrier engine convert to `contributes` on their manifest',
  // The AGENTIC note above, now machine-readable (agent-preprocessing DESIGN §7):
  // baselining's deterministic preprocessing detects this and escalates to the
  // agent stage instead of advancing the stamp past it. There are no mechanical
  // member-side ops, so this is the record's whole member-side work.
  agentic: {
    model: 'sonnet',
    instructions: 'If a member local pack (.claudinite/local/packs/) composed a barrier by importing the shared engine, convert it to the contribution shape: move the barrier object (id, edges, description, why, doc, crossingExcuse, gateDir) onto the local pack manifest under `contributes`, and add the mechanism pack to its `requires`. A member with no such local pack needs nothing.',
  },
};

=== .claudinite/shared/migrations/active_migrations/2026-07-19-local-pack-namespace.mjs ===
// Namespace local-pack declarations: a repo's own pack (.claudinite/local_packs/<name>/)
// is declared in .claudinite-checks.json by its namespaced token `local_packs/<name>`,
// not a bare id — self-documenting, and a canon id can never be claimed by accident
// (the bare form shared the canon namespace; a collision was only CAUGHT by the
// discoverPacks shadow guard, never prevented).
//
// Seed-style, like grow-with-claudinite-seed: the WRITE rides baselining — its
// declaration-normalization step runs in the member checkout (which knows which
// declared ids are local packs) and rewrites any bare local-pack declaration to the
// namespaced form (see the baselining worker doc). This record holds no ops of its
// own; it is the convergence telemetry. The engine accepts BOTH forms throughout (and
// after — packEntryId's strip is the permanent parser, not a tolerance this record
// carries), so retiring strands nothing.
//
// legacyPresent: a member still declares a bare id (string entry or entry-object id,
// no `local_packs/` prefix) whose pack lives in its own .claudinite/local_packs/ tree.
// A bare id with no such local pack is a canon declaration — not this record's business.
// retire: 'auto' — self-retires once the fleet has converged and stayed quiet a cycle.
export default {
  id: 'local-pack-namespace',
  landed: '2026-07-19',
  summary: 'local-pack declarations namespaced as local_packs/<name> (baselining rewrites bare ids; the engine accepts both forms)',
  legacyPresent: async (exists, read) => {
    const raw = await read('.claudinite-checks.json');
    if (raw == null) return false;
    let packs;
    try { ({ packs } = JSON.parse(raw)); } catch { return false; }
    if (!Array.isArray(packs)) return false;
    for (const e of packs) {
      const id = typeof e === 'string' ? e : e?.id;
      if (typeof id !== 'string' || id.startsWith('local_packs/')) continue;
      if (await exists(`.claudinite/local_packs/${id}/pack.mjs`)) return true;
    }
    return false;
  },
  retire: 'auto',
};

=== .claudinite/shared/migrations/active_migrations/2026-07-15-local-packs-enablement.mjs ===
// Enable a repo's own local packs (.claudinite/local_packs/ — tracked project
// prose/checks/skills/run_daily the engine runs alongside the canon). Two pieces
// of member-side plumbing must be in place before a repo can safely COMMIT local
// packs, and BOTH ride baselining (not this record):
//   1. the tracked sync hook must preserve local_packs/ across its dir swap —
//      baselining refreshes the member's tracked mount/sync-claudinite.sh from the
//      canon every run (the canon copy carries the preserve block); and
//   2. .gitignore must re-include .claudinite/local_packs/ — bootstrap.md step 3
//      (idempotent, re-applied by baselining) appends the negation.
// The canon commit that ships those touches mount/ and bootstrap.md, so
// canonChanged fires fleet-wide and baselining converges every member the first
// night after — no per-repo content is materialized here (a project AUTHORS its
// own local packs; the move of existing capture is a judgment task carried by the
// project-instructions and growth-extract skills, never a mechanical alias).
//
// This record is therefore TELEMETRY ONLY: the retire pass reports how many
// members still carry the pre-enablement hook, so the owner can see when the whole
// fleet is safe to author local packs in. `legacyPresent` reads the member's
// tracked hook and returns true while it lacks the local_packs preserve block.
//
// retire: 'manual' — the enablement lives in baselining + bootstrap, not here, so
// this record holds no tolerance to strand; retire it by hand once the retire pass
// reports zero members on the legacy shape.
export default {
  id: 'local-packs-enablement',
  landed: '2026-07-15',
  summary: 'members preserve + track .claudinite/local_packs/ (sync-hook preserve via baselining, gitignore via bootstrap)',
  legacyPresent: async (exists, read) => {
    const hook = await read('.claudinite/mount/sync-claudinite.sh');
    if (hook == null) return false; // pre-mount shape — the mount-folder migration tracks that, not this
    // Converged once the tracked hook carries the preserve block for local_packs.
    return !hook.includes('$dest/local_packs');
  },
  retire: 'manual',
};

