1	import { finding } from '../../engine/checks/helpers/findings.mjs';
2	import { wikiPages, sectionBody, BULLET, DATED, realDateUTC } from './lib.mjs';
3	
4	// Growth-log discipline: every top-level bullet in the section leads with its
5	// run date (bold or plain — the invariant is dating, not typography), the date
6	// is a real calendar date, and a seeded page has at least one entry (a page
7	// with content and an empty log never recorded its seed). Indented
8	// continuation lines and prose paragraphs are ignored; the bullet/date grammar
9	// is lib.mjs's, shared with the freshness advisory so the two checks can never
10	// disagree about what an entry date is. Deliberately absent: ordering (a
11	// backdated correction is legitimate) and any wall-clock rule (staleness is
12	// the freshness advisory's job).
13	const FIX = 'lead every growth-log bullet with the run date, e.g. "- **2026-07-15** — what changed"; append the seed entry when the page is first committed';
14	
15	const rule = {
16	  id: 'product-wiki-growth-log',
17	  severity: 'blocking',
18	  doc: 'packs/product-wiki/README.md',
19	  description: 'Every Growth log entry is a dated bullet (real YYYY-MM-DD), and a seeded page has at least one',
20	  why: 'undated or absent log entries break the audit trail and the freshness signal every other growth mechanism keys on',
21	
22	  run(ctx) {
23	    const out = [];
24	    for (const page of wikiPages(ctx.files)) {
25	      const text = ctx.read(page);
26	      if (text === null) continue;
27	      const section = sectionBody(text, 'growth log');
28	      if (section === null) continue; // page-sections owns the missing heading
29	      let bullets = 0;
30	      for (const { line, text: t } of section) {
31	        if (!BULLET.test(t)) continue; // top-level bullets only
32	        bullets += 1;
